{% (
  $unesc := function($s) {
    $replace($replace($replace($replace($replace($replace($s,
      '&nbsp;', '\u00a0'), '&#39;', "'"), '&quot;', '"'), '&lt;', '<'), '&gt;', '>'), '&amp;', '&')
  };
  $norm := function($s) {
    $replace($replace($replace($replace($replace($s, '\u2019', "'"), '\u2018', "'"), '\u201c', '"'), '\u201d', '"'), '\u00a0', ' ')
  };
  $c0 := $substringBefore($substringAfter($substringAfter(steps.fetch.output.body, 'doc-content'), '>'), 'google-footer');
  $c := $replace($c0, /<style[\s\S]*?<\/style>/, '');
  $c := $replace($c, /<script[\s\S]*?<\/script>/, '');
  $rawBlocks := $split($c, /<\/(?:p|h[1-6])>/);
  $nrb := $count($rawBlocks);
  $blocks := $map([1..$nrb-1], function($i) { $unesc($replace($rawBlocks[$i-1], /<[^>]*>/, '')) });

  $needle := $norm(input.snippet);
  $hits := $filter($map([1..$count($blocks)], function($i) {
    ( $nb := $norm($blocks[$i-1]);
      $contains($nb, $needle) ? { 'para': $i-1, 'offset': $length($substringBefore($nb, $needle)) } : null )
  }), function($h) { $exists($h.para) });
  { 'found': $count($hits) = 1, 'matches': $count($hits),
    'para': $hits[0].para, 'offset': $hits[0].offset, 'snippet_chars': $length($needle),
    'next_step': $count($hits) = 0 ? 'NOT FOUND: re-run docs.read and quote the text exactly.' :
                 $count($hits) > 1 ? 'AMBIGUOUS: use a longer snippet with more surrounding words.' :
                 'Walk with these numbers verbatim: docs.cursor_to_paragraph {paragraph: ' & $string($hits[0].para) & '} then docs.cursor_forward {chars: ' & $string($hits[0].offset) & '}; to select the snippet add docs.select_forward {chars: ' & $string($length($needle)) & '}.' }
) %}

{% (
  $unesc := function($s) {
    $replace($replace($replace($replace($replace($replace($s,
      '&nbsp;', '\u00a0'), '&#39;', "'"), '&quot;', '"'), '&lt;', '<'), '&gt;', '>'), '&amp;', '&')
  };
  $norm := function($s) {
    $replace($replace($replace($replace($replace($s, '\u2019', "'"), '\u2018', "'"), '\u201c', '"'), '\u201d', '"'), '\u00a0', ' ')
  };
  $c0 := $substringBefore($substringAfter($substringAfter(steps.fetch.output.body, 'doc-content'), '>'), 'google-footer');
  $c := $replace($c0, /<style[\s\S]*?<\/style>/, '');
  $c := $replace($c, /<script[\s\S]*?<\/script>/, '');
  $rawBlocks := $split($c, /<\/(?:p|h[1-6])>/);
  $nrb := $count($rawBlocks);
  $blocks := $map([1..$nrb-1], function($i) { $unesc($replace($rawBlocks[$i-1], /<[^>]*>/, '')) });
  $needle := $norm(input.target);
  $hits := $filter($map([1..$count($blocks)], function($i) {
    ( $nb := $norm($blocks[$i-1]);
      $contains($nb, $needle) ? { 'para': $i-1, 'offset': $length($substringBefore($nb, $needle)) } : null )
  }), function($h) { $exists($h.para) });
