  $paragraph := $reduce([1..$count($blocks)], function($acc,$i){ $i-1 = $para ? $blocks[$i-1] : $acc }, '');
  {
    'found': $matches = 1,
    'matches': $matches,
    'paragraph': $para,
    'offset': $offset,
    'target_chars': $length($needle),
    'target': input.target,
    'replacement': input.replacement,
    'original_paragraph': $paragraph,
    'safe_to_execute': $matches = 1,
    'execute_sequence': $matches = 1 ? [
      'Ensure the Docs tab is foreground/active and the editor body is focused.',
      'docs.cursor_to_paragraph { paragraph: ' & $string($para) & ' }',
      'docs.cursor_forward { chars: ' & $string($offset) & ', text: original_paragraph }',
      'docs.select_forward { chars: ' & $string($length($needle)) & ' }',
      input.replacement = '' ? 'keyboard.press { key: Delete, trusted: true }' : 'text.type { text: replacement, trusted: true }',
      'Wait about 2s, then docs.read { doc_id, paragraph: ' & $string($para) & ' }',
      'Verify the replacement and its neighbor words; if wrong, docs.undo and retry with a wider target span.'
    ] : [],
    'next_step': $matches = 0 ? 'NOT FOUND: re-run docs.read and quote the current text exactly.' : $matches > 1 ? 'AMBIGUOUS: quote a longer surrounding span until matches is 1.' : 'Execute the returned sequence exactly; do not use Find/Ctrl+F and do not count characters yourself.'
  }
) %}
